clip.use("centi");

clip.defineParams({
  val0: {type: "number", default:0, interpolable: true},
  val1: {type: "number", default:0, interpolable: false},
  color: {type: "color", default:"#ffffff", interpolable: true},
  pos: {type:"vec2", interpolable: true}
});

setup(() => {
  size(1920, 1080);
  bg(33);
});

onFrame(({ time, frame, progress, compTime, compFrame, runTime, runFrame, bar, beat }) => {
  clear();
  bg(clip.color);
  col(255);
  let y = 0;
  for(const name of clip.paramNames){
    if (clip.isNew[name]) sendOsc("/" + name, clip[name]);
    bmTxt(name + ": " + clip[name],0,y);
    y += 40;
  } 

});

onEnter(({ time, frame, progress, compTime, compFrame, runTime, runFrame, bar, beat }) => {
});

onBeat(({ time, frame, progress, compTime, compFrame, runTime, runFrame, bar, beat }) => {
